import java.util.*;

public class Main {
    public static void main(String[] args) {
        int n = 5, src = 0;
        int[][] edges = {{0,1,4},{0,2,1},{2,1,2},{1,3,1},{2,3,5},{3,4,3}};
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        String s = "";
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            s += e[0] + "->" + e[1] + "(" + e[2] + ") ";
        }
        System.out.println("Edges: " + s);
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[src] = 0;
        // min-heap of {distance, node}: the closest unfinished node comes out first
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.add(new int[]{0, src});
        int stale = 0;
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], u = top[1];
            if (d > dist[u]) { stale++; continue; }   // old entry: a better one was already used
            for (int[] e : adj.get(u)) {
                // relax: is going through u a shorter way to reach e[0]?
                if (d + e[1] < dist[e[0]]) {
                    dist[e[0]] = d + e[1];
                    pq.add(new int[]{dist[e[0]], e[0]});
                }
            }
        }
        System.out.println("Shortest distances from " + src + ": " + Arrays.toString(dist));
        System.out.println("Stale heap entries skipped: " + stale);
        // Time O((V + E) log V), space O(V + E)
    }
}

