// tiny binary min-heap of [distance, node] pairs (JavaScript has none built in)
const heap = [];
function swap(i, j) { const t = heap[i]; heap[i] = heap[j]; heap[j] = t; }
function push(x) {
  heap.push(x);
  let i = heap.length - 1;
  while (i > 0 && heap[(i - 1) >> 1][0] > heap[i][0]) { swap(i, (i - 1) >> 1); i = (i - 1) >> 1; }
}
function pop() {
  const top = heap[0], last = heap.pop();
  if (heap.length > 0) {
    heap[0] = last;
    let i = 0;
    while (true) {
      let m = i; const l = 2 * i + 1, r = l + 1;
      if (l < heap.length && heap[l][0] < heap[m][0]) m = l;
      if (r < heap.length && heap[r][0] < heap[m][0]) m = r;
      if (m === i) break;
      swap(i, m); i = m;
    }
  }
  return top;
}

const dist = new Array(n).fill(Infinity);
dist[src] = 0;
push([0, src]);
let stale = 0;
while (heap.length > 0) {
  const [d, u] = pop();                 // the closest unfinished node comes out first
  if (d > dist[u]) { stale++; continue; } // old entry: a better one was already used
  for (const [v, w] of adj[u]) {
    // relax: is going through u a shorter way to reach v?
    if (d + w < dist[v]) { dist[v] = d + w; push([dist[v], v]); }
  }
}
console.log("Shortest distances from " + src + ": [" + dist.join(", ") + "]");
console.log("Stale heap entries skipped: " + stale);
// Time O((V + E) log V), space O(V + E)

