class Program {
    static void Main() {
        int n = 5, src = 0;
        int[][] edges = { new[]{0,1,4}, new[]{0,2,1}, new[]{2,1,2}, new[]{1,3,1}, new[]{2,3,5}, new[]{3,4,3} };
        var adj = new List<int[]>[n];
        for (int i = 0; i < n; i++) adj[i] = new List<int[]>();
        string s = "";
        foreach (var e in edges) {
            adj[e[0]].Add(new[]{ e[1], e[2] });
            s += e[0] + "->" + e[1] + "(" + e[2] + ") ";
        }
        Console.WriteLine("Edges: " + s);
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = int.MaxValue;
        dist[src] = 0;
        // sorted set used as a min-heap; each entry is distance * n + node packed in one number
        var pq = new SortedSet<long>();
        pq.Add(0L * n + src);
        int stale = 0;
        while (pq.Count > 0) {
            long top = pq.Min;                 // the closest unfinished node comes out first
            pq.Remove(top);
            int d = (int)(top / n), u = (int)(top % n);
            if (d > dist[u]) { stale++; continue; }   // old entry: a better one was already used
            foreach (var e in adj[u]) {
                // relax: is going through u a shorter way to reach e[0]?
                if (d + e[1] < dist[e[0]]) {
                    dist[e[0]] = d + e[1];
                    pq.Add((long)dist[e[0]] * n + e[0]);
                }
            }
        }
        Console.WriteLine("Shortest distances from " + src + ": [" + string.Join(", ", dist) + "]");
        Console.WriteLine("Stale heap entries skipped: " + stale);
        // Time O((V + E) log V), space O(V + E)
    }
}

code.java:
import java.util.*;

public class Main {
    static final int INF = 1000000000;
    static int n = 4;
    static int[][] edges = {{0,1,2},{0,2,3},{2,1,-2},{1,3,1}};

    // Dijkstra: a node is locked the first time it is picked and never changed again
    static int[] dijkstra() {
        int[] dist = new int[n];
        boolean[] done = new boolean[n];
        Arrays.fill(dist, INF);
        dist[0] = 0;
        for (int step = 0; step < n; step++) {
            int u = -1;
            for (int i = 0; i < n; i++) if (!done[i] && (u == -1 || dist[i] < dist[u])) u = i;
            done[u] = true;
            for (int[] e : edges)
                if (e[0] == u && !done[e[1]] && dist[u] + e[2] < dist[e[1]]) dist[e[1]] = dist[u] + e[2];
        }
        return dist;
    }

    // Bellman-Ford: relax every edge V - 1 times, so late improvements still spread
    static int[] bellmanFord() {
        int[] dist = new int[n];
        Arrays.fill(dist, INF);
        dist[0] = 0;
        for (int round = 0; round < n - 1; round++)
            for (int[] e : edges)
                if (dist[e[0]] < INF && dist[e[0]] + e[2] < dist[e[1]]) dist[e[1]] = dist[e[0]] + e[2];
        return dist;
    }

    public static void main(String[] args) {
        System.out.println("Edges: 0->1(2) 0->2(3) 2->1(-2) 1->3(1), source 0");
        System.out.println("Dijkstra (wrong):     " + Arrays.toString(dijkstra()));
        System.out.println("Bellman-Ford (right): " + Arrays.toString(bellmanFord()));
        // Node 1 was locked at 2 before the route 0->2->1 (cost 1) was seen.
        // Dijkstra here O(V^2 + V*E); Bellman-Ford O(V*E) time, O(V) space
    }
}

