import java.util.*;

public class Main {
    public static void main(String[] args) {
        String[] grid = {"0101", "1101", "0100", "0110"};   // 1 = wall, 0 = free
        int R = 4, C = 4, INF = 1000000000;
        int[] dist = new int[R * C];
        Arrays.fill(dist, INF);
        dist[0] = 0;
        ArrayDeque<Integer> dq = new ArrayDeque<>();
        dq.add(0);                                   // a cell is stored as r * C + c
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        while (!dq.isEmpty()) {
            int cur = dq.pollFirst();
            int r = cur / C, c = cur % C;
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
                int w = grid[nr].charAt(nc) - '0';   // stepping into a wall costs 1
                int nxt = nr * C + nc;
                if (dist[cur] + w < dist[nxt]) {
                    dist[nxt] = dist[cur] + w;
                    // cost 0 goes to the front, cost 1 to the back: the deque stays sorted
                    if (w == 0) dq.addFirst(nxt); else dq.addLast(nxt);
                }
            }
        }
        for (String row : grid) System.out.println(row);
        System.out.println("Minimum walls to break from top-left to bottom-right: " + dist[R * C - 1]);
        // Time O(R*C), space O(R*C): no heap, every deque operation is O(1)
    }
}

