code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        int n = 5;
        int[][] edges = {{0,1,1},{1,2,2},{2,3,-4},{3,1,1},{3,4,2}};
        int[] dist = new int[n];          // all 0: like a virtual source joined to every node
        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int x = -1;
        for (int round = 0; round < n; round++) {      // V rounds: the last one is the test
            x = -1;
            for (int[] e : edges) {
                if (dist[e[0]] + e[2] < dist[e[1]]) {
                    dist[e[1]] = dist[e[0]] + e[2];
                    parent[e[1]] = e[0];
                    x = e[1];                          // remember a node that still improved
                }
            }
        }
        System.out.println("Edges: 0->1(1) 1->2(2) 2->3(-4) 3->1(1) 3->4(2)");
        if (x == -1) { System.out.println("No negative cycle"); return; }
        for (int i = 0; i < n; i++) x = parent[x];     // step back V times: now inside the cycle
        List<Integer> cyc = new ArrayList<>();
        cyc.add(x);
        for (int v = parent[x]; v != x; v = parent[v]) cyc.add(v);
        Collections.reverse(cyc);                      // parents go backwards, so reverse
        String s = "";
        for (int v : cyc) s += v + " -> ";
        System.out.println("Negative cycle: " + s + cyc.get(0));
        // Time O(V*E), space O(V)
    }
}

