public class Main {
    static final int INF = 1000000000;

    static void show(String title, int[][] d) {
        System.out.println(title);
        for (int[] row : d) {
            String s = "";
            for (int x : row) s += (x >= INF ? "INF" : String.valueOf(x)) + " ";
            System.out.println("  " + s);
        }
    }

    public static void main(String[] args) {
        int n = 4;
        int[][] edges = {{0,1,3},{0,2,8},{1,2,-2},{2,3,2},{3,0,4}};
        int[][] d = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) d[i][j] = (i == j) ? 0 : INF;
        for (int[] e : edges) d[e[0]][e[1]] = e[2];       // start with the direct edges
        show("Direct edges:", d);
        // k is the newest vertex we are allowed to pass through; it must be the outer loop
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j])
                        d[i][j] = d[i][k] + d[k][j];  // going i -> k -> j is cheaper
        show("All-pairs shortest distances:", d);
        boolean neg = false;
        for (int i = 0; i < n; i++) if (d[i][i] < 0) neg = true;   // a negative diagonal = negative cycle
        System.out.println("Negative cycle: " + (neg ? "yes" : "no"));
        // Time O(V^3), space O(V^2)
    }
}

