import java.util.*;

public class Main {
    static int[] parent;
    static int find(int x) { while (parent[x] != x) x = parent[x]; return x; }

    public static void main(String[] args) {
        int n = 5;
        int[][] edges = {{0,1,2},{0,2,6},{1,2,3},{1,3,8},{2,3,5},{2,4,7},{3,4,9}};
        Arrays.sort(edges, (a, b) -> a[2] - b[2]);       // Kruskal: cheapest edges first
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        boolean[] inMst = new boolean[edges.length];
        int total = 0;
        String s = "";
        for (int i = 0; i < edges.length; i++) {
            int a = find(edges[i][0]), b = find(edges[i][1]);
            if (a == b) continue;                         // would close a cycle: skip
            parent[a] = b;
            inMst[i] = true;
            total += edges[i][2];
            s += edges[i][0] + "-" + edges[i][1] + "(" + edges[i][2] + ") ";
        }
        System.out.println("MST edges: " + s + "total " + total);
        // Cut property: for every way to split the vertices into two groups,
        // the cheapest edge crossing the split must be in the MST (weights are distinct).
        int cuts = 0;
        boolean ok = true;
        for (int mask = 1; mask < (1 << n) - 1; mask++) {
            int best = -1;
            for (int i = 0; i < edges.length; i++) {
                boolean crosses = ((mask >> edges[i][0]) & 1) != ((mask >> edges[i][1]) & 1);
                if (crosses && (best == -1 || edges[i][2] < edges[best][2])) best = i;
            }
            if (!inMst[best]) ok = false;
            cuts++;
        }
        System.out.println("Splits checked: " + cuts + ", cheapest crossing edge always in MST: " + ok);
        // Kruskal O(E log E); the check is O(2^V * E), only for this tiny demo
    }
}

