code.java:
import java.util.*;

public class Main {
    static int n = 5;
    static int[][] edges = {{0,1,2},{0,2,6},{1,2,3},{1,3,8},{2,3,5},{2,4,7},{3,4,9}};
    static int[] parent = new int[n];
    static int find(int x) { while (parent[x] != x) x = parent[x]; return x; }

    // Kruskal: sort the edge list, add an edge when it joins two different groups
    static int kruskal() {
        int[][] sorted = edges.clone();
        Arrays.sort(sorted, (a, b) -> a[2] - b[2]);
        for (int i = 0; i < n; i++) parent[i] = i;
        int total = 0;
        for (int[] e : sorted) {
            int a = find(e[0]), b = find(e[1]);
            if (a != b) { parent[a] = b; total += e[2]; }
        }
        return total;
    }

    // Prim (array version): grow one tree, always adding the closest outside vertex
    static int prim() {
        int INF = 1000000000;
        int[][] w = new int[n][n];
        for (int[] e : edges) { w[e[0]][e[1]] = e[2]; w[e[1]][e[0]] = e[2]; }
        int[] key = new int[n];            // key[v] = cheapest edge from the tree to v
        boolean[] inTree = new boolean[n];
        Arrays.fill(key, INF);
        key[0] = 0;
        int total = 0;
        for (int step = 0; step < n; step++) {
            int u = -1;
            for (int i = 0; i < n; i++) if (!inTree[i] && (u == -1 || key[i] < key[u])) u = i;
            inTree[u] = true;
            total += key[u];
            for (int v = 0; v < n; v++)
                if (w[u][v] > 0 && !inTree[v] && w[u][v] < key[v]) key[v] = w[u][v];
        }
        return total;
    }

    public static void main(String[] args) {
        System.out.println("Edges: 0-1(2) 0-2(6) 1-2(3) 1-3(8) 2-3(5) 2-4(7) 3-4(9)");
        System.out.println("Kruskal MST weight: " + kruskal());   // O(E log E)
        System.out.println("Prim MST weight:    " + prim());      // O(V^2) with arrays
    }
}

