  for (const [u, v, c] of edges) { w[u][v] = c; w[v][u] = c; }
  const key = new Array(n).fill(INF);      // key[v] = cheapest edge from the tree to v
  const inTree = new Array(n).fill(false);
  key[0] = 0;
  let total = 0;
