public class Main {
    static int[] parent, size;
    static int components;

    static int find(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];
        // path compression: point every node on the way straight at the root
        while (parent[x] != root) { int next = parent[x]; parent[x] = root; x = next; }
        return root;
    }

    static boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;                 // already in the same set
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;                            // smaller tree goes under the bigger one
        size[ra] += size[rb];
        components--;
        return true;
    }

    public static void main(String[] args) {
        int n = 8;
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        components = n;
        int[][] pairs = {{0,1},{2,3},{1,3},{4,5},{0,2},{6,7},{5,7}};
        for (int[] p : pairs)
            System.out.println("union(" + p[0] + ", " + p[1] + ") -> " + (union(p[0], p[1]) ? "merged" : "already together"));
        System.out.println("Components: " + components);
        System.out.println("0 and 3 connected: " + (find(0) == find(3)));
        System.out.println("0 and 4 connected: " + (find(0) == find(4)));
        // Each operation is amortised O(alpha(n)), almost constant; space O(n)
    }
}

