import java.util.*;

public class Main {
    static final int INF = 1000000000;
    static int n = 4, src = 0, dst = 3, k = 1;
    static int[][] flights = {{0,1,100},{1,2,100},{2,0,100},{1,3,600},{2,3,200}};

    // Bellman-Ford limited to k + 1 rounds: round i allows routes with at most i flights
    static int cheapest(boolean useCopy) {
        int[] dist = new int[n];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        for (int round = 0; round <= k; round++) {
            // read from the previous round only, so one round adds exactly one flight
            int[] prev = useCopy ? dist.clone() : dist;
            for (int[] f : flights)
                if (prev[f[0]] < INF && prev[f[0]] + f[2] < dist[f[1]])
                    dist[f[1]] = prev[f[0]] + f[2];
        }
        return dist[dst] >= INF ? -1 : dist[dst];
    }

    public static void main(String[] args) {
        System.out.println("Flights: 0->1(100) 1->2(100) 2->0(100) 1->3(600) 2->3(200)");
        System.out.println("From 0 to 3 with at most " + k + " stop");
        System.out.println("With a copy per round (correct): " + cheapest(true));
        System.out.println("Updating in place (wrong):       " + cheapest(false));
        // In place, 0->1->2->3 (2 stops, cost 400) sneaks in during a single round.
        // Time O(K * E), space O(V)
    }
}

