import java.util.*;

public class Main {
    public static void main(String[] args) {
        int n = 5, INF = 1000000000;
        int[][] edges = {{0,1,1},{0,2,1},{1,3,1},{2,3,1},{0,3,2},{3,4,1}};   // undirected
        int[][] w = new int[n][n];
        for (int[] e : edges) { w[e[0]][e[1]] = e[2]; w[e[1]][e[0]] = e[2]; }
        int[] dist = new int[n];
        long[] ways = new long[n];
        boolean[] done = new boolean[n];
        Arrays.fill(dist, INF);
        dist[0] = 0;
        ways[0] = 1;                                   // one way to stand at the start
        for (int step = 0; step < n; step++) {
            int u = -1;                                // closest unfinished node
            for (int i = 0; i < n; i++) if (!done[i] && (u == -1 || dist[i] < dist[u])) u = i;
            done[u] = true;                            // ways[u] is complete from here on
            for (int v = 0; v < n; v++) {
                if (w[u][v] == 0) continue;
                int nd = dist[u] + w[u][v];
                if (nd < dist[v]) { dist[v] = nd; ways[v] = ways[u]; }   // strictly better: replace
                else if (nd == dist[v]) ways[v] += ways[u];              // a tie: add the routes
            }
        }
        System.out.println("Edges: 0-1(1) 0-2(1) 1-3(1) 2-3(1) 0-3(2) 3-4(1)");
        System.out.println("dist: " + Arrays.toString(dist));
        System.out.println("ways: " + Arrays.toString(ways));
        System.out.println("Shortest 0 -> 4 costs " + dist[4] + " and can be done in " + ways[4] + " ways");
        // Time O(V^2) with this array version (O(E log V) with a heap), space O(V^2) for the matrix
    }
}

