import java.util.*;

public class Main {
    static int n = 4;
    static int[][] edges = {{0,1,5},{1,3,5},{0,2,1},{2,3,8}};   // undirected

    // Same Dijkstra loop; only the rule for extending a path changes.
    static int best(boolean useMax) {
        int INF = 1000000000;
        int[] cost = new int[n];
        boolean[] done = new boolean[n];
        Arrays.fill(cost, INF);
        cost[0] = 0;
        for (int step = 0; step < n; step++) {
            int u = -1;
            for (int i = 0; i < n; i++) if (!done[i] && (u == -1 || cost[i] < cost[u])) u = i;
            done[u] = true;
            for (int[] e : edges) {
                if (e[0] != u && e[1] != u) continue;
                int v = (e[0] == u) ? e[1] : e[0];
                // sum of edges, or the biggest single edge on the path
                int nc = useMax ? Math.max(cost[u], e[2]) : cost[u] + e[2];
                if (nc < cost[v]) cost[v] = nc;      // both rules never get better by adding an edge
            }
        }
        return cost[n - 1];
    }

    public static void main(String[] args) {
        System.out.println("Edges: 0-1(5) 1-3(5) 0-2(1) 2-3(8), from 0 to 3");
        System.out.println("Smallest total (sum of edges):      " + best(false));   // route 0-2-3
        System.out.println("Smallest worst edge (max of edges): " + best(true));    // route 0-1-3
        // Time O(V^2 + V*E) in this simple form, space O(V)
    }
}

