import java.util.*;

public class Main {
    static int R = 8, C = 8, start = 3 * 8 + 0, goal = 3 * 8 + 7;   // cell = r * C + c

    // h = straight grid distance to the goal; it never overestimates (admissible)
    static int h(int cell, boolean useH) {
        return useH ? Math.abs(cell / C - goal / C) + Math.abs(cell % C - goal % C) : 0;
    }

    static void run(String name, boolean useH) {
        int INF = 1000000000, expanded = 0;
        int[] g = new int[R * C];
        boolean[] closed = new boolean[R * C];
        Arrays.fill(g, INF);
        g[start] = 0;
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        while (true) {
            int u = -1;
            // pick the open cell with the smallest g + h (ties: the one nearer the goal)
            for (int i = 0; i < R * C; i++) {
                if (closed[i] || g[i] == INF) continue;
                int f = g[i] + h(i, useH);
                if (u == -1 || f < g[u] + h(u, useH) || (f == g[u] + h(u, useH) && h(i, useH) < h(u, useH))) u = i;
            }
            closed[u] = true;
            expanded++;
            if (u == goal) break;                    // the goal is final: stop early
            for (int k = 0; k < 4; k++) {
                int nr = u / C + dr[k], nc = u % C + dc[k];
                if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
                if (g[u] + 1 < g[nr * C + nc]) g[nr * C + nc] = g[u] + 1;
            }
        }
        System.out.println(name + ": path length " + g[goal] + ", cells expanded " + expanded);
    }

    public static void main(String[] args) {
        System.out.println("8x8 open grid, from (3,0) to (3,7)");
        run("Dijkstra (h = 0)", false);     // spreads out in every direction
        run("A* (Manhattan h)", true);      // heads for the goal, same answer
        // Worst case is the same as Dijkstra; a good heuristic just cuts the cells visited
    }
}

