public class Main {
    public static void main(String[] args) {
        int n = 5, INF = 1000000000;
        int[][] edges = {{0,1,4},{0,2,1},{2,1,2},{1,3,5},{3,4,3},{4,2,6}};   // one-way roads
        int[][] d = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) d[i][j] = (i == j) ? 0 : INF;
        for (int[] e : edges) d[e[0]][e[1]] = e[2];
        // Precompute once: Floyd-Warshall fills the whole table in O(V^3)
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j])
                        d[i][j] = d[i][k] + d[k][j];
        System.out.println("Edges: 0->1(4) 0->2(1) 2->1(2) 1->3(5) 3->4(3) 4->2(6)");
        int[][] queries = {{0,3},{3,1},{1,0},{2,2},{4,1}};
        // Each query is now a single table lookup: O(1)
        for (int[] q : queries) {
            int ans = d[q[0]][q[1]];
            System.out.println("dist(" + q[0] + ", " + q[1] + ") = " + (ans >= INF ? "unreachable" : String.valueOf(ans)));
        }
        // Total O(V^3 + Q) time, O(V^2) space
    }
}

