import java.util.*;

public class Main {
    static final int INF = 1000000000;
    static int n = 6, m = 10, seed = 1;
    static int rnd() { seed = (seed * 75 + 74) % 65537; return seed; }   // tiny repeatable random

    // Fast version under test: Dijkstra (array form)
    static int[] dijkstra(int[][] edges) {
        int[] dist = new int[n];
        boolean[] done = new boolean[n];
        Arrays.fill(dist, INF);
        dist[0] = 0;
        for (int step = 0; step < n; step++) {
            int u = -1;
            for (int i = 0; i < n; i++) if (!done[i] && (u == -1 || dist[i] < dist[u])) u = i;
            done[u] = true;
            if (dist[u] == INF) continue;
            for (int[] e : edges) if (e[0] == u && dist[u] + e[2] < dist[e[1]]) dist[e[1]] = dist[u] + e[2];
        }
        return dist;
    }

    // Slow but obviously correct oracle: Bellman-Ford
    static int[] oracle(int[][] edges) {
        int[] dist = new int[n];
        Arrays.fill(dist, INF);
        dist[0] = 0;
        for (int round = 0; round < n - 1; round++)
            for (int[] e : edges) if (dist[e[0]] < INF && dist[e[0]] + e[2] < dist[e[1]]) dist[e[1]] = dist[e[0]] + e[2];
        return dist;
    }

    public static void main(String[] args) {
        int tests = 200, mismatches = 0, withUnreachable = 0;
        for (int t = 0; t < tests; t++) {
            int[][] edges = new int[m][];
            // random small graph: self-loops, parallel edges and zero weights all appear
            for (int i = 0; i < m; i++) { int u = rnd() % n, v = rnd() % n, w = rnd() % 10; edges[i] = new int[]{u, v, w}; }
            int[] a = dijkstra(edges), b = oracle(edges);
            if (!Arrays.equals(a, b)) mismatches++;
            for (int x : b) if (x == INF) { withUnreachable++; break; }
        }
        System.out.println("Random graphs tested: " + tests + " (6 nodes, 10 edges, weights 0..9)");
        System.out.println("Graphs with an unreachable node: " + withUnreachable);
        System.out.println("Mismatches between Dijkstra and the oracle: " + mismatches);
        // Per test: Dijkstra O(V^2 + V*E), oracle O(V*E)
    }
}

