using System;

class Program {
    const int INF = 1000000000;
    static int n = 6, m = 10, seed = 1;
    static int Rnd() { seed = (seed * 75 + 74) % 65537; return seed; }   // tiny repeatable random

    // Fast version under test: Dijkstra (array form)
    static int[] Dijkstra(int[][] edges) {
        int[] dist = new int[n];
        bool[] done = new bool[n];
        for (int i = 0; i < n; i++) dist[i] = INF;
        dist[0] = 0;
        for (int step = 0; step < n; step++) {
            int u = -1;
            for (int i = 0; i < n; i++) if (!done[i] && (u == -1 || dist[i] < dist[u])) u = i;
            done[u] = true;
            if (dist[u] == INF) continue;
            foreach (var e in edges) if (e[0] == u && dist[u] + e[2] < dist[e[1]]) dist[e[1]] = dist[u] + e[2];
        }
        return dist;
    }

    // Slow but obviously correct oracle: Bellman-Ford
    static int[] Oracle(int[][] edges) {
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = INF;
        dist[0] = 0;
        for (int round = 0; round < n - 1; round++)
            foreach (var e in edges) if (dist[e[0]] < INF && dist[e[0]] + e[2] < dist[e[1]]) dist[e[1]] = dist[e[0]] + e[2];
        return dist;
    }

    static void Main() {
        int tests = 200, mismatches = 0, withUnreachable = 0;
        for (int t = 0; t < tests; t++) {
            int[][] edges = new int[m][];
            // random small graph: self-loops, parallel edges and zero weights all appear
            for (int i = 0; i < m; i++) { int u = Rnd() % n, v = Rnd() % n, w = Rnd() % 10; edges[i] = new[]{ u, v, w }; }
            int[] a = Dijkstra(edges), b = Oracle(edges);
            bool same = true, unreachable = false;
            for (int i = 0; i < n; i++) { if (a[i] != b[i]) same = false; if (b[i] == INF) unreachable = true; }
            if (!same) mismatches++;
            if (unreachable) withUnreachable++;
        }
        Console.WriteLine("Random graphs tested: " + tests + " (6 nodes, 10 edges, weights 0..9)");
        Console.WriteLine("Graphs with an unreachable node: " + withUnreachable);
        Console.WriteLine("Mismatches between Dijkstra and the oracle: " + mismatches);
        // Per test: Dijkstra O(V^2 + V*E), oracle O(V*E)
    }
}
